import{_ as r,o,c as a,ao as t}from"./chunks/framework.Cs3u8zxb.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),d={name:"changelog.md"};function c(l,e,i,n,s,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="Changelog" tabindex="-1">Changelog <a class="header-anchor" href="#Changelog" aria-label="Permalink to &quot;Changelog {#Changelog}&quot;">​</a></h1><h2 id="Unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#Unreleased" aria-label="Permalink to &quot;Unreleased {#Unreleased}&quot;">​</a></h2><ul><li><p>Move all packages to sibling top-level directories and make the root project workspace-only.</p></li><li><p>Move code to ZarrCore.jl with low dependencies</p></li><li><p>Move HTTP, GCS, S3, and ZIP backends into <code>ZarrHTTP</code>, <code>ZarrGCS</code>, <code>ZarrS3</code>, and <code>ZarrZip</code>.</p></li><li><p>Move Blosc, zlib, and Zstandard support into <code>ZarrBlosc</code>, <code>ZarrZlib</code>, and <code>ZarrZstd</code>; each provides its v2 compressor and v3 codec.</p></li><li><p>Loading <code>ZarrBlosc</code> makes <code>default_compressor()</code> return <code>BloscCompressor()</code>; bare <code>ZarrCore</code> returns <code>NoCompressor()</code>.</p></li><li><p>Register external compressors, codecs, and URL stores at load time. URL patterns are matched by specificity.</p></li><li><p>AWSS3 remains an optional dependency of <code>ZarrS3</code>.</p></li><li><p>Make <code>missing_chunk_return_code!</code> and <code>gcs_credentials</code> public. Stop exposing <code>DateTime64</code>, <code>PermanentZarrCache</code>, <code>BloscCodec</code>, and <code>GzipCodec</code> through <code>Zarr</code>.</p></li><li><p>Declare an explicit public API <a href="https://github.com/JuliaIO/Zarr.jl/pull/317" target="_blank" rel="noreferrer">#317</a>. Every store, codec, filter and compressor type, and every documented extension point, is now <code>public</code>; the set of exported names is unchanged. Internals (<code>Metadata</code>, <code>ZarrFormat</code>, <code>is_zarray</code>, <code>is_zgroup</code>, <code>normalize_path</code>, <code>MaxLengthString</code>, ...) are no longer reachable as <code>Zarr.x</code> and must be accessed via <code>Zarr.ZarrCore.x</code></p></li><li><p>Fixed <code>fill_as_missing=true</code> on zarr v3 arrays, which threw <code>cannot reinterpret UInt8 as Union{Missing,Float64}</code> when decoding an initialized chunk.</p></li><li><p>Add <code>ZarrTrimmable</code>, an opt-in subpackage for programs compiled with <code>juliac --trim=safe</code>. <code>@zarr_reader(dtypes, ndims, codecs, stores; tag, path_store, read_strategy)</code> generates a closed-set reader that adds <code>zopen(f, reader, path)</code>, <code>zopen(reader, path)</code> (at most 3 dtype x ndims x zarr_format variants) and <code>zcreate(reader, path, T, dims; ...)</code> methods over a <code>Union</code>-typed codec pool and store pool; <code>ArrayMeta</code> with <code>read_meta</code>/<code>write_meta</code>is an<code>Any</code>-free mirror of<code>.zarray</code>.<code>ZarrTrimmable</code>is not re-exported by<code>Zarr</code>.</p></li><li><p>Add the <code>codec_id(::Type{C})</code> extension point to <code>ZarrCore</code> (the numcodecs id a compressor type is stored under; <code>&quot;&quot;</code> for <code>NoCompressor</code>), implemented by <code>ZarrZstd</code>, <code>ZarrZlib</code> and <code>ZarrBlosc</code>, and a keyword-option constructor <code>CompressorJSON(id; cname, clevel, shuffle, blocksize, level, checksum)</code>.</p></li><li><p>Add a statically typed Zarr v3 open. <code>zopen(T, Val(N), store, path; pipeline = P)</code> opens a <code>zarr.json</code> array with <code>P&lt;:V3Pipeline</code> naming the whole codec chain, e.g. <code>V3Pipeline{Tuple{}, BytesCodec, Tuple{ZstdV3Codec}}</code>; the result is a fully concrete <code>ZArray{T,N,S,MetadataV3{T,N,P,ChunkKeyEncoding}}</code> and the path is juliac <code>--trim=safe</code> clean. It is built on an <code>Any</code>-free <code>zarr.json</code> schema (<code>ZarrJsonV3</code>, <code>CodecJSON</code>, <code>CodecConfigJSON</code>, <code>ChunkGridJSON</code>, <code>ChunkGridConfigJSON</code>, <code>ChunkKeyEncodingJSON</code>, <code>ChunkKeyEncodingConfigJSON</code>, the accessors <code>chunk_grid_json</code>, <code>chunk_key_encoding_json</code>, <code>codecs_json</code>, and <code>parse_zarrjson</code>), all <code>public</code>.</p></li><li><p>Add the v3 codec extension points <code>Codecs.V3Codecs.codec_name(::Type{C})</code> (the spec name a codec type is stored under; the instance <code>name(c)</code> now falls back to it) and <code>Codecs.V3Codecs.getCodec(::Type{C}, ::CodecJSON, ctx)</code>, implemented by <code>ZarrZstd</code>, <code>ZarrZlib</code> and <code>ZarrBlosc</code> next to their v3 codecs, plus <code>Codecs.V3Codecs.pipeline_from_json(P, codecs, ctx)</code>, which validates a stored codec chain against a requested pipeline type. A codec joins a typed <code>V3Pipeline</code> once it defines both.</p></li><li><p><code>zcreate(...; zarr_format = 3)</code> is juliac <code>--trim=safe</code> clean: v3 array creation now writes a single <code>zarr.json</code> (with <code>attributes</code> included) through <code>write_new_metadata</code> instead of a read-modify-write. Writing a <em>sharded</em> v3 array from a compiled program is still not trim-clean.</p></li><li><p><code>@zarr_reader</code> gains <code>zarr_format</code> (<code>(2,)</code>, <code>(3,)</code> or <code>(2, 3)</code>; a bare integer is accepted) and <code>v3_codecs</code> (a non-empty tuple of <code>V3Codec{:bytes,:bytes}</code> types, required when 3 is in the pool). A v3 reader emits a <code>BBPool_tag</code> bytes-&gt;bytes codec pool and a <code>P_tag = V3Pipeline{Tuple{}, BytesCodec, Vector{BBPool_tag}}</code>, and its visitor tries <code>.zarray</code> then <code>zarr.json</code>. <code>codecs</code> is optional when 2 is not in the pool (no <code>zcreate</code> methods are emitted then).</p></li><li><p>The statically typed <code>zopen(::Type{T}, ::Val{N}, ...)</code> is now a single keyword method taking <code>compressor</code> (v2) or <code>pipeline</code> (v3); exactly one of the two is required and giving neither or both is an <code>ArgumentError</code>. <code>compressor</code> is no longer a mandatory keyword of a separate method, but code that passed it keeps working unchanged.</p></li><li><p><strong>Breaking for direct callers</strong>: every Zarr v3 <code>JSON.lower</code> method (codecs, <code>lower_chunk_key_encoding</code>, <code>lower3</code>) now returns a <code>NamedTuple</code> instead of a <code>Dict{String,Any}</code>, so a lowered document is indexed with symbols (<code>lowered[:codecs]</code>) rather than strings. The JSON written to disk is unchanged.</p></li><li><p>Fix the v3 <code>data_type</code> written for complex arrays: <code>ComplexF32</code>/<code>ComplexF64</code> are now stored as <code>&quot;complex64&quot;</code>/<code>&quot;complex128&quot;</code> (the spec names) instead of <code>&quot;complexf32&quot;</code>/<code>&quot;complexf64&quot;</code>, which Zarr.jl itself could not read back.</p></li></ul><h2 id="v0.10.2-2026-08-19" tabindex="-1">v0.10.2 - 2026-08-19 <a class="header-anchor" href="#v0.10.2-2026-08-19" aria-label="Permalink to &quot;v0.10.2 - 2026-08-19 {#v0.10.2-2026-08-19}&quot;">​</a></h2><ul><li><p>Support HTTP.jl 2.x and drop 1.x <a href="https://github.com/JuliaIO/Zarr.jl/pull/322" target="_blank" rel="noreferrer">#322</a></p></li><li><p>Add logo and favicon to docs <a href="https://github.com/JuliaIO/Zarr.jl/pull/307" target="_blank" rel="noreferrer">#307</a></p></li><li><p>Support reading and writing variable-length strings <a href="https://github.com/JuliaIO/Zarr.jl/pull/311" target="_blank" rel="noreferrer">#311</a></p></li><li><p>Add more informative show method for S3Store <a href="https://github.com/JuliaIO/Zarr.jl/pull/320/" target="_blank" rel="noreferrer">#320</a></p></li><li><p>Fix complex fill values in python interop tests <a href="https://github.com/JuliaIO/Zarr.jl/pull/316" target="_blank" rel="noreferrer">#316</a></p></li><li><p>Remove lru keyword from zopen, should use DiskArrays.cache instead</p></li></ul><h2 id="v0.10.1-2026-07-07" tabindex="-1">v0.10.1 - 2026-07-07 <a class="header-anchor" href="#v0.10.1-2026-07-07" aria-label="Permalink to &quot;v0.10.1 - 2026-07-07 {#v0.10.1-2026-07-07}&quot;">​</a></h2><ul><li><p>Add caching to menu, update sharding description <a href="https://github.com/JuliaIO/Zarr.jl/pull/306" target="_blank" rel="noreferrer">#306</a></p></li><li><p>Added support for the Zarr V3 <code>fixed_length_utf32</code> string data type <a href="https://github.com/JuliaIO/Zarr.jl/pull/305" target="_blank" rel="noreferrer">#305</a></p></li><li><p>Added consolidated_metadata reading and writing support for v3 <a href="https://github.com/JuliaIO/Zarr.jl/pull/287" target="_blank" rel="noreferrer">#287</a></p></li><li><p>Fix the <code>ConcurrentRead</code> write path silently dropping chunk writes; affected stores such as <code>S3Store</code> wrote array metadata but no data chunks <a href="https://github.com/JuliaIO/Zarr.jl/pull/297" target="_blank" rel="noreferrer">#297</a></p></li><li><p>Added reading compat for stores produced in python with <code>numcodecs.blosc</code> <a href="https://github.com/JuliaIO/Zarr.jl/pull/286" target="_blank" rel="noreferrer">#286</a></p></li><li><p>Bump HTTP compat to 2 <a href="https://github.com/JuliaIO/Zarr.jl/pull/284" target="_blank" rel="noreferrer">#284</a></p></li><li><p>V2 performance improvements <a href="https://github.com/JuliaIO/Zarr.jl/pull/280" target="_blank" rel="noreferrer">#280</a></p><ul><li><p><code>readblock!</code> fast path for single-chunk full-reads that bypasses the readtask channel and the chunk-shaped scratch buffer, decoding straight into the output array</p></li><li><p><code>writeblock!</code> fast path for single-chunk full-overwrites that bypasses the readtask/writetask channels and the chunk-shaped scratch buffer, encoding straight from the input array into the store</p></li><li><p>Zero-copy chunk write for <code>NoCompressor</code> + no filters: the single-chunk fastpath hands a <code>reinterpret(UInt8, ain)</code> view straight to the store, skipping the chunk-sized <code>Vector{UInt8}</code> allocation + memcpy</p></li><li><p><code>NoCompressor</code> writes: replace <code>append!</code> over the reinterpret view with bulk <code>resize!</code> + <code>copyto!</code> in the generic <code>zcompress!</code> fallback</p></li><li><p><code>NoCompressor</code> reads: bulk-copy <code>zuncompress!</code> method dispatched on <code>::NoCompressor</code> bypasses <code>copyto!(::Array, ::ReinterpretArray)</code>&#39;s element-by-element walk</p></li><li><p><code>getchunkarray_undef</code> skips the dead zero-fill of the chunk-shaped scratch buffer on full-overwrite paths</p></li></ul></li><li><p>Added manual pagination in order to go beyond the default 1k <a href="https://github.com/JuliaIO/Zarr.jl/pull/282" target="_blank" rel="noreferrer">#282</a></p></li><li><p>Added <code>wait</code> to writetask in <code>writeblock!</code> <a href="https://github.com/JuliaIO/Zarr.jl/pull/281" target="_blank" rel="noreferrer">#281</a></p></li><li><p>Fix getattrs for v3 <a href="https://github.com/JuliaIO/Zarr.jl/pull/277" target="_blank" rel="noreferrer">#277</a></p></li><li><p>Add <code>CachingStore</code>, a store that caches reads from a remote store in a local cache store <a href="https://github.com/JuliaIO/Zarr.jl/pull/231" target="_blank" rel="noreferrer">#231</a></p></li><li><p>Fix CondaPkg branch in CI, use release version instead <a href="https://github.com/JuliaIO/Zarr.jl/pull/273" target="_blank" rel="noreferrer">#273</a></p></li><li><p>Fix creation of on-disk arrays that do not fit in memory <a href="https://github.com/JuliaIO/Zarr.jl/pull/269" target="_blank" rel="noreferrer">#269</a></p></li><li><p>Add another consistent caching approach through <code>zarrcache</code> <a href="https://github.com/JuliaIO/Zarr.jl/pull/293" target="_blank" rel="noreferrer">#299</a></p></li></ul><h2 id="v0.10.0-2026-04-24" tabindex="-1">v0.10.0 - 2026-04-24 <a class="header-anchor" href="#v0.10.0-2026-04-24" aria-label="Permalink to &quot;v0.10.0 - 2026-04-24 {#v0.10.0-2026-04-24}&quot;">​</a></h2><ul><li><p>Enable <code>sharding_indexed</code> codec for Zarr v3 <a href="https://github.com/JuliaIO/Zarr.jl/pull/241" target="_blank" rel="noreferrer">#241</a></p><ul><li><p>outer chunks (shards) are now split into inner chunks with a byte-range index, enabling efficient partial reads of large arrays</p></li><li><p>Python zarr interoperability tests for sharded arrays using real fixtures generated via PythonCall/zarr-python</p></li><li><p>Function-based codec registration system with typed <code>CodecEntry</code> for extensible V3 codec parsing</p></li><li><p><code>sharding_indexed</code> codec context propagation: inner codec parser now receives element-size context so codecs like <code>blosc</code> get the correct <code>typesize</code></p></li><li><p><code>sharding_indexed</code> decode double-shift bug for <code>index_location=:start</code>: shard index offsets are now treated as absolute byte offsets from the shard start in all cases</p></li><li><p><code>sharding_indexed</code> decode fill value: <code>zdecode!</code> now accepts an optional <code>fill_value</code> argument so missing inner chunks are filled with the array fill value instead of <code>zero(T)</code></p></li><li><p><code>pipeline_decode!</code> for <code>V2Pipeline</code> now accepts the <code>fill_value</code> keyword argument (ignored, but required to match the unified call site in <code>ZArray.readblock!</code>)</p></li><li><p>Ragged inner chunks in <code>ShardingCodec</code> handled correctly</p></li></ul></li><li><p>fixes UI str parsing <a href="https://github.com/JuliaIO/Zarr.jl/pull/259" target="_blank" rel="noreferrer">#259</a></p></li><li><p>added zarr_format to ZGroup <a href="https://github.com/JuliaIO/Zarr.jl/pull/258" target="_blank" rel="noreferrer">#258</a></p></li><li><p>Add support for S3Path and remove deprecated global_aws_config() <a href="https://github.com/JuliaIO/Zarr.jl/pull/253" target="_blank" rel="noreferrer">#253</a></p></li><li><p>(docs) get started <a href="https://github.com/JuliaIO/Zarr.jl/pull/246" target="_blank" rel="noreferrer">#246</a></p></li><li><p>update badges <a href="https://github.com/JuliaIO/Zarr.jl/pull/245" target="_blank" rel="noreferrer">#245</a></p></li><li><p>setup vitepress <a href="https://github.com/JuliaIO/Zarr.jl/pull/243" target="_blank" rel="noreferrer">#243</a></p></li><li><p>Registration system for chunk key encoding <a href="https://github.com/JuliaIO/Zarr.jl/pull/242" target="_blank" rel="noreferrer">#242</a></p></li><li><p>test: Consolidate CondaPkg.add calls <a href="https://github.com/JuliaIO/Zarr.jl/pull/240" target="_blank" rel="noreferrer">#240</a></p></li><li><p>test: Read Julia-generated v3 fixtures with Python zarr <a href="https://github.com/JuliaIO/Zarr.jl/pull/239" target="_blank" rel="noreferrer">#239</a></p></li><li><p>Use CondaPkg.jl#206 for nightly, fix manifest_uuid_path <a href="https://github.com/JuliaIO/Zarr.jl/pull/238" target="_blank" rel="noreferrer">#238</a></p></li><li><p>fix docs build <a href="https://github.com/JuliaIO/Zarr.jl/pull/237" target="_blank" rel="noreferrer">#237</a></p></li><li><p>consolidate methods <a href="https://github.com/JuliaIO/Zarr.jl/pull/235" target="_blank" rel="noreferrer">#235</a></p></li><li><p>Add AbstractChunkKeyEncoding <a href="https://github.com/JuliaIO/Zarr.jl/pull/234" target="_blank" rel="noreferrer">#234</a></p></li><li><p>V3 codec pipeline, group creation, and Python interop <a href="https://github.com/JuliaIO/Zarr.jl/pull/232" target="_blank" rel="noreferrer">#232</a></p></li><li><p>Add read support for big endian <a href="https://github.com/JuliaIO/Zarr.jl/pull/230" target="_blank" rel="noreferrer">#230</a></p></li><li><p>Indent method/type signatures on docstrings <a href="https://github.com/JuliaIO/Zarr.jl/pull/229" target="_blank" rel="noreferrer">#229</a></p></li><li><p>Promote header levels in tutorial.md <a href="https://github.com/JuliaIO/Zarr.jl/pull/228" target="_blank" rel="noreferrer">#228</a></p></li><li><p>Continue on v3 PR <a href="https://github.com/JuliaIO/Zarr.jl/pull/226" target="_blank" rel="noreferrer">#226</a></p></li><li><p>move AWSS3 into extension <a href="https://github.com/JuliaIO/Zarr.jl/pull/224" target="_blank" rel="noreferrer">#224</a></p></li></ul>',9)])])}const g=r(d,[["render",c]]);export{u as __pageData,g as default};
